<?php
declare(strict_types=1);
namespace App\Services;
use App\Repositories\{FeeRepository,StudentRepository};
final class FeeService{
public function __construct(private readonly FeeRepository$fees,private readonly StudentRepository$students){}
public function ensureInvoice(array$student,int$institute,string$month,int$user):array{if($x=$this->fees->invoice((int)$student['id'],$month))return$x;$pdo=$this->fees->db()->connection();$pdo->beginTransaction();try{$items=$this->fees->scopedItems($institute,$month,$student['class_name'],$student['registration_no']);$tuition=$student['monthly_fee_override']!==null?(float)$student['monthly_fee_override']:(float)$student['monthly_tuition'];$lines=[['particular'=>'Monthly Tuition Fee','amount'=>$tuition]];foreach($items as$item)if(!in_array($item['item_key'],['monthly_tuition','previous_balance','discount'],true)&&(float)$item['amount']>0)$lines[]=['particular'=>$item['label'],'amount'=>(float)$item['amount']];$subtotal=array_sum(array_column($lines,'amount'));$value=(float)($student['discount_value']??$student['discount_in_fee']??0);$discount=($student['discount_type']??'percentage')==='fixed'?$value:round($subtotal*($value/100),2);$discount=min($subtotal,max(0,$discount));$previous=$this->fees->previousBalance((int)$student['id'],$month);$total=max(0,$subtotal-$discount+$previous);$now=date('Y-m-d H:i:s');$this->fees->createInvoice(['student_id'=>$student['id'],'fee_month'=>$month,'invoice_no'=>'INV-'.str_replace('-','',$month).'-'.$student['id'],'subtotal'=>$subtotal,'discount'=>$discount,'previous_balance'=>$previous,'total_amount'=>$total,'paid_amount'=>0,'remaining_amount'=>$total,'status'=>'unpaid','created_by'=>$user,'created_at'=>$now,'updated_at'=>$now],$lines);$pdo->commit();return$this->fees->invoice((int)$student['id'],$month)??throw new \RuntimeException('Invoice creation failed.');}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
public function collect(array$student,int$institute,string$month,float$amount,string$method,?string$reference,int$user):int{$this->ensureInvoice($student,$institute,$month,$user);$pdo=$this->fees->db()->connection();$pdo->beginTransaction();try{$invoice=$this->fees->invoice((int)$student['id'],$month,true);if($amount<=0||$amount>(float)$invoice['remaining_amount'])throw new \InvalidArgumentException('Payment must be greater than zero and not exceed the remaining balance.');$payment=$this->fees->addPayment((int)$invoice['id'],(int)$student['id'],$amount,$method,$reference,$user);$paid=(float)$invoice['paid_amount']+$amount;$this->fees->updateInvoice((int)$invoice['id'],$paid,max(0,(float)$invoice['total_amount']-$paid));$pdo->commit();return$payment;}catch(\Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
}
